-- LexAmplify RLS Phase 2 step 2: core owner-keyed tables.
-- Inert while the app connects as the rolbypassrls=True postgres role.
-- Pattern + rationale: see 001_rls_role_and_clauses.sql and README.md.
-- dms_docs (workspace-only key) is deferred to its own step.

ALTER TABLE saved_drafts ENABLE ROW LEVEL SECURITY;
ALTER TABLE saved_drafts FORCE  ROW LEVEL SECURITY;
DROP POLICY IF EXISTS saved_drafts_rls_select ON saved_drafts;
DROP POLICY IF EXISTS saved_drafts_rls_insert ON saved_drafts;
DROP POLICY IF EXISTS saved_drafts_rls_update ON saved_drafts;
DROP POLICY IF EXISTS saved_drafts_rls_delete ON saved_drafts;
CREATE POLICY saved_drafts_rls_select ON saved_drafts FOR SELECT USING (owner_user_id = NULLIF(current_setting('app.user_id', true), '')::int);
CREATE POLICY saved_drafts_rls_insert ON saved_drafts FOR INSERT WITH CHECK (owner_user_id = NULLIF(current_setting('app.user_id', true), '')::int);
CREATE POLICY saved_drafts_rls_update ON saved_drafts FOR UPDATE USING (owner_user_id = NULLIF(current_setting('app.user_id', true), '')::int) WITH CHECK (owner_user_id = NULLIF(current_setting('app.user_id', true), '')::int);
CREATE POLICY saved_drafts_rls_delete ON saved_drafts FOR DELETE USING (owner_user_id = NULLIF(current_setting('app.user_id', true), '')::int);
ALTER TABLE draft_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE draft_sessions FORCE  ROW LEVEL SECURITY;
DROP POLICY IF EXISTS draft_sessions_rls_select ON draft_sessions;
DROP POLICY IF EXISTS draft_sessions_rls_insert ON draft_sessions;
DROP POLICY IF EXISTS draft_sessions_rls_update ON draft_sessions;
DROP POLICY IF EXISTS draft_sessions_rls_delete ON draft_sessions;
