CREATE POLICY draft_sessions_rls_insert ON draft_sessions FOR INSERT WITH CHECK (user_id = NULLIF(current_setting('app.user_id', true), '')::int);
CREATE POLICY draft_sessions_rls_update ON draft_sessions FOR UPDATE USING (user_id = NULLIF(current_setting('app.user_id', true), '')::int) WITH CHECK (user_id = NULLIF(current_setting('app.user_id', true), '')::int);
CREATE POLICY draft_sessions_rls_delete ON draft_sessions FOR DELETE USING (user_id = NULLIF(current_setting('app.user_id', true), '')::int);
ALTER TABLE matters ENABLE ROW LEVEL SECURITY;
ALTER TABLE matters FORCE  ROW LEVEL SECURITY;
DROP POLICY IF EXISTS matters_rls_select ON matters;
DROP POLICY IF EXISTS matters_rls_insert ON matters;
DROP POLICY IF EXISTS matters_rls_update ON matters;
DROP POLICY IF EXISTS matters_rls_delete ON matters;
CREATE POLICY matters_rls_select ON matters FOR SELECT USING ((owner_user_id = NULLIF(current_setting('app.user_id', true), '')::int OR (team_id IS NOT NULL AND EXISTS (SELECT 1 FROM team_memberships tm WHERE tm.team_id = matters.team_id AND tm.user_id = NULLIF(current_setting('app.user_id', true), '')::int))) AND (NULLIF(current_setting('app.workspace_id', true), '') IS NULL OR workspace_id IS NULL OR workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::int));
CREATE POLICY matters_rls_insert ON matters FOR INSERT WITH CHECK (owner_user_id = NULLIF(current_setting('app.user_id', true), '')::int);
CREATE POLICY matters_rls_update ON matters FOR UPDATE USING ((owner_user_id = NULLIF(current_setting('app.user_id', true), '')::int OR (team_id IS NOT NULL AND EXISTS (SELECT 1 FROM team_memberships tm WHERE tm.team_id = matters.team_id AND tm.user_id = NULLIF(current_setting('app.user_id', true), '')::int)))) WITH CHECK ((owner_user_id = NULLIF(current_setting('app.user_id', true), '')::int OR (team_id IS NOT NULL AND EXISTS (SELECT 1 FROM team_memberships tm WHERE tm.team_id = matters.team_id AND tm.user_id = NULLIF(current_setting('app.user_id', true), '')::int))));
CREATE POLICY matters_rls_delete ON matters FOR DELETE USING (owner_user_id = NULLIF(current_setting('app.user_id', true), '')::int);
